// Builds the line-matching prompt from the same files the evals read (prompts/, schemas/).
// Mirrors evals/hotel_evals/match.py (build_match_system_prompt, match_user_message); a test runs
// this code and compares the output with the Python.
const fs = require('fs');
const DIR = '/opt/hotel-ops';
const ANNOTATIONS = ['description', '$schema', '$id', 'title'];

// Drop schema prose (the rules already say it) but keep structure; only string-valued annotation
// keys go, so a property that is itself named "description" stays.
const strip = (node) => {
  if (Array.isArray(node)) return node.map(strip);
  if (node && typeof node === 'object') {
    return Object.fromEntries(
      Object.entries(node)
        .filter(([k, v]) => !(ANNOTATIONS.includes(k) && typeof v === 'string'))
        .map(([k, v]) => [k, strip(v)]),
    );
  }
  return node;
};

const ctx = $input.first().json.result; // reconcile_candidates(): {invoice_number, pending_lines, candidates}
const schema = JSON.parse(fs.readFileSync(`${DIR}/schemas/line_match.json`, 'utf8'));
const template = fs.readFileSync(`${DIR}/prompts/line_match.md`, 'utf8');
if (!template.includes('{{SCHEMA}}')) throw new Error('prompt file lost its {{SCHEMA}} placeholder');
const system = template.replace('{{SCHEMA}}', () => JSON.stringify(strip(schema)));

const dollars = (c) => `${Math.trunc(c / 100)}.${String(c % 100).padStart(2, '0')}`;
const num = (v) => Number(v).toFixed(3).replace(/\.?0+$/, '');

const lines = [`Invoice ${ctx.invoice_number}`, '', 'Invoice lines to match:'];
for (const l of ctx.pending_lines) {
  lines.push(
    `- line ${l.line_no}: "${l.description}", quantity ${num(l.quantity)}, unit ${l.unit || 'no unit printed'}, ` +
      `unit price $${dollars(l.unit_price_cents)}, line total $${dollars(l.line_total_cents)}`,
  );
}
lines.push('', 'Purchase order lines still unmatched (choose only among these):');
for (const c of ctx.candidates) {
  lines.push(
    `- PO line ${c.po_line_no}: SKU ${c.supplier_sku || 'none'}, "${c.description}", ` +
      `unit ${c.unit}, ordered ${num(c.quantity)}, price $${dollars(c.unit_price_cents)}`,
  );
}

return [{ json: { invoice_id: ctx.invoice_id, system, user: lines.join('\n'), attempt: 1, context: ctx } }];

// CLAUDE.md principle 2 again, for the line matcher: the model's reply is validated before any of it is
// used. Same interpreter as `Validate Extraction` (spliced in verbatim), against schemas/line_match.json,
// then the checks a schema cannot express. Mirrors match_errors() in evals/hotel_evals/match.py.
const fs = require('fs');
const DIR = '/opt/hotel-ops';

// >>> schema-interpreter (byte-identical in every validation node; evals/tests/test_workflow_code.py enforces it)
// Annotations carry no constraint. `format` is one: dates are checked for real by the node itself.
const ANNOTATIONS = ['$schema', '$id', 'title', 'description', 'format'];
const CONSTRAINTS = [
  'type', 'enum', 'pattern', 'minLength', 'minimum', 'exclusiveMinimum', 'maximum',
  'minItems', 'items', 'required', 'properties', 'additionalProperties',
];
const TYPES = ['string', 'number', 'integer', 'boolean', 'null', 'object', 'array'];

const jsonType = (v) => (v === null ? 'null' : Array.isArray(v) ? 'array' : typeof v);
const isType = (v, t) => (t === 'integer' ? typeof v === 'number' && Number.isInteger(v) : jsonType(v) === t);

const assertSupported = (node, path) => {
  for (const [key, value] of Object.entries(node)) {
    if (!ANNOTATIONS.includes(key) && !CONSTRAINTS.includes(key)) {
      throw new Error(`schema keyword "${key}" at ${path || '(root)'} is not supported by this validator`);
    }
    if (key === 'properties') {
      for (const [name, sub] of Object.entries(value)) assertSupported(sub, `${path}/${name}`);
    } else if (key === 'items') {
      assertSupported(value, `${path}/items`);
    } else if (key === 'type') {
      for (const t of [].concat(value)) {
        if (!TYPES.includes(t)) throw new Error(`schema type "${t}" at ${path || '(root)'} is not supported by this validator`);
      }
    }
  }
};

const check = (node, value, path, errors) => {
  const where = path || '(root)';
  if (node.type !== undefined) {
    const allowed = [].concat(node.type);
    if (!allowed.some((t) => isType(value, t))) {
      errors.push(`${where}: expected ${allowed.join(' or ')}, got ${jsonType(value)}`);
      return;
    }
  }
  if (node.enum !== undefined && !node.enum.includes(value)) {
    errors.push(`${where}: ${JSON.stringify(value)} is not one of ${JSON.stringify(node.enum)}`);
  }
  if (typeof value === 'string') {
    if (node.minLength !== undefined && [...value].length < node.minLength) {
      errors.push(`${where}: shorter than ${node.minLength} characters`);
    }
    if (node.pattern !== undefined && !new RegExp(node.pattern, 'u').test(value)) {
      errors.push(`${where}: ${JSON.stringify(value)} does not match ${node.pattern}`);
    }
  }
  if (typeof value === 'number') {
    if (node.minimum !== undefined && value < node.minimum) {
      errors.push(`${where}: ${value} is less than the minimum ${node.minimum}`);
    }
    if (node.exclusiveMinimum !== undefined && !(value > node.exclusiveMinimum)) {
      errors.push(`${where}: ${value} must be greater than ${node.exclusiveMinimum}`);
    }
    if (node.maximum !== undefined && value > node.maximum) {
      errors.push(`${where}: ${value} is greater than the maximum ${node.maximum}`);
    }
  }
  if (Array.isArray(value)) {
    if (node.minItems !== undefined && value.length < node.minItems) {
      errors.push(`${where}: fewer than ${node.minItems} items`);
    }
    if (node.items !== undefined) value.forEach((v, i) => check(node.items, v, `${path}/${i + 1}`, errors));
  }
  if (jsonType(value) === 'object') {
    for (const key of node.required ?? []) {
      if (!(key in value)) errors.push(`${where}: '${key}' is a required property`);
    }
    const props = node.properties ?? {};
    if (node.additionalProperties === false) {
      for (const key of Object.keys(value)) {
        if (!(key in props)) errors.push(`${where}: unexpected property '${key}'`);
      }
    }
    for (const [key, sub] of Object.entries(props)) {
      if (key in value) check(sub, value[key], `${path}/${key}`, errors);
    }
  }
};

// All schema errors for `value`, as strings; throws if the schema uses something unsupported.
const validateAgainst = (schema, value) => {
  assertSupported(schema, '');
  const errors = [];
  check(schema, value, '', errors);
  return errors;
};
// <<< schema-interpreter

// One validator run per attempt, so the run index is the attempt number.
const attempt = $runIndex + 1;
const ctx = $('Build Match Prompt').first().json.context;

// Same hand-over shapes as the extraction validator: parsed fields, {text}, or {error}.
const reply = $input.first().json;
const isText = typeof reply.text === 'string' && Object.keys(reply).length === 1;
const modelError = reply.error !== undefined ? String(reply.error.message ?? reply.error) : undefined;
const raw = isText ? reply.text : modelError !== undefined ? '' : JSON.stringify(reply);

const schema = JSON.parse(fs.readFileSync(`${DIR}/schemas/line_match.json`, 'utf8'));

const errorsFor = (output) => {
  const errors = validateAgainst(schema, output);
  if (errors.length > 0) return errors.slice(0, 12);

  const asked = ctx.pending_lines.map((l) => l.line_no);
  const offered = new Set(ctx.candidates.map((c) => c.po_line_no));
  const answered = output.matches.map((m) => m.invoice_line_no);
  for (const n of asked) {
    const times = answered.filter((a) => a === n).length;
    if (times !== 1) errors.push(`invoice line ${n} must be answered exactly once, it was answered ${times} times`);
  }
  for (const n of [...new Set(answered)].filter((a) => !asked.includes(a)).sort((a, b) => a - b)) {
    errors.push(`invoice line ${n} was not asked about`);
  }
  const used = new Map();
  for (const m of output.matches) {
    if (m.po_line_no === null) continue;
    if (!offered.has(m.po_line_no)) {
      errors.push(`PO line ${m.po_line_no} is not one of the lines offered`);
    } else if (used.has(m.po_line_no)) {
      errors.push(`PO line ${m.po_line_no} is used for invoice lines ${used.get(m.po_line_no)} and ${m.invoice_line_no}; use it once`);
    } else {
      used.set(m.po_line_no, m.invoice_line_no);
    }
  }
  return errors;
};

// A parse failure is the model's fault (it gets the one retry); a failed call is infrastructure and
// fails the execution: reconciliation then stays pending and can simply be run again.
let parsed;
let errors;
if (modelError !== undefined) {
  if (!/JSON/i.test(modelError)) throw new Error(`model server failure: ${modelError}`);
  errors = [`output is not valid JSON (${modelError})`];
} else {
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    errors = [`output is not valid JSON (${e.message})`];
  }
}
if (errors === undefined) errors = errorsFor(parsed);

if (errors.length === 0) {
  return [{ json: { valid: true, attempt, matches: parsed.matches, raw, errors: [] } }];
}
return [{ json: { valid: false, attempt, errors, raw } }];

// The model matched the lines it was asked about, and the answer is valid.
const prompt = $('Build Match Prompt').first().json;
const verdict = $input.first().json; // Validate Matches
return [
  {
    json: {
      invoice_id: prompt.invoice_id,
      matches: verdict.matches,
      context: { execution_id: $execution.id, workflow_id: $workflow.id, workflow_name: $workflow.name },
      matcher: { status: 'matched', attempts: verdict.attempt, lines: verdict.matches.length },
    },
  },
];

// The one retry for the matcher: a single user message with the original request, the failed
// answer and the numbered errors. Mirrors match_retry_message() in evals/hotel_evals/match.py.
const fs = require('fs');

const prompt = $('Build Match Prompt').first().json;
const failed = $input.first().json; // Validate Matches' verdict for the attempt that just failed

let user = fs.readFileSync('/opt/hotel-ops/prompts/line_match_retry.md', 'utf8');
const fill = [
  ['{{CONTEXT}}', prompt.user],
  ['{{PREVIOUS_OUTPUT}}', failed.raw],
  ['{{ERRORS}}', failed.errors.map((e) => `- ${e}`).join('\n')],
];
for (const [key, value] of fill) user = user.split(key).join(value);

return [{ json: { system: prompt.system, user, attempt: failed.attempt + 1 } }];

// The model's answer was invalid twice. Reconcile without it: the lines it was asked about stay
// unmatched, which ends in needs_review (never a silent guess).
const prompt = $('Build Match Prompt').first().json;
const verdict = $input.first().json; // Validate Matches, second failure
return [
  {
    json: {
      invoice_id: prompt.invoice_id,
      matches: [],
      context: { execution_id: $execution.id, workflow_id: $workflow.id, workflow_name: $workflow.name },
      matcher: { status: 'failed', attempts: verdict.attempt, errors: verdict.errors },
    },
  },
];

// Every line matched by SKU or description: no model call was needed.
const invoiceId = $('Get Candidates').first().json.result.invoice_id;
return [
  {
    json: {
      invoice_id: invoiceId,
      matches: [],
      context: { execution_id: $execution.id, workflow_id: $workflow.id, workflow_name: $workflow.name },
      matcher: { status: 'not_needed' },
    },
  },
];

// What the workflow returns: the reconciliation, what the matcher did, and the approval request.
const result = $('Reconcile').first().json.result;
const prepared = ['Prepare Matched', 'Prepare Failed Match', 'Prepare Unneeded']
  .map((name) => $(name))
  .find((node) => node.isExecuted);
// Requesting the approval is continue-on-fail: a problem there must not hide a reconciliation that is stored.
// It reports itself as pending, and running the reconciliation again requests the approval again.
const out = $input.first().json; // Request Approval
const approval = out.error !== undefined ? { result: 'pending', error: String(out.error.message ?? out.error) } : out.approval;
return [{ json: { ...result, matcher: prepared.first().json.matcher, approval } }];
